import os
from pathlib import Path

root = Path('/workspace')
cache_dirs = []
pyc_files = []
venvs = []

for dirpath, dirnames, filenames in os.walk(root, followlinks=False):
    current = Path(dirpath)
    kept = []
    for name in dirnames:
        path = current / name
        if path.is_symlink():
            continue
        if name == '__pycache__':
            cache_dirs.append(path)
            continue
        if name in {'venv', '.venv', 'env'}:
            venvs.append(path)
            continue
        kept.append(name)
    dirnames[:] = kept
    for name in filenames:
        if name.endswith('.pyc'):
            pyc_files.append(current / name)

def size(path):
    try:
        if path.is_file() or path.is_symlink():
            return path.lstat().st_size
        total = 0
        for base, dirs, files in os.walk(path, followlinks=False):
            for filename in files:
                item = Path(base) / filename
                try:
                    total += item.lstat().st_size
                except OSError:
                    pass
        return total
    except OSError:
        return 0

def human(n):
    units = ['B', 'KiB', 'MiB', 'GiB', 'TiB']
    value = float(n)
    for unit in units:
        if value < 1024 or unit == units[-1]:
            return f'{value:.1f} {unit}' if unit != 'B' else f'{int(value)} B'
        value /= 1024

records = []
for kind, paths in [('__pycache__', cache_dirs), ('.pyc', pyc_files), ('virtualenv', venvs)]:
    for path in sorted(paths):
        records.append((kind, str(path), size(path)))

for kind, path, n in records:
    print(f'{kind}\t{n}\t{human(n)}\t{path}')
print('SUMMARY')
for kind in ('__pycache__', '.pyc', 'virtualenv'):
    selected = [r for r in records if r[0] == kind]
    total = sum(r[2] for r in selected)
    print(f'{kind}\t{len(selected)}\t{total}\t{human(total)}')
unique_total = sum(r[2] for r in records)
print(f'all\t{len(records)}\t{unique_total}\t{human(unique_total)}')
